                def other = pveHostUrl(address)
                if (!other || !seen.add(other)) { return }
                def id = 'failover-' + pveWildValue(address)
                try {
                    def (otherHost, otherPort) = pveTroubleTarget(other)
                    probes.connect(otherHost, otherPort)
                    probes.read(other, '/version')
